     1	import type { TLShape } from "tldraw";
     2	
     3	// An allowlist, not a parse check: the link renders as <a href>, so admitting
     4	// arbitrary protocols would make `javascript:` an XSS vector.
     5	const ALLOWED_WEB_PROTOCOLS = new Set(["http:", "https:", "mailto:"]);
     6	
     7	// Only obsidian://open?...file=... -- a bare `obsidian:` check would admit
     8	// action URIs like advanced-uri's commandid from a shared canvas.
     9	const isAllowedObsidianUrl = (url: URL): boolean =>
    10	  url.host === "open" && !!url.searchParams.get("file");
    11	
    12	export const isAllowedTextLinkUrl = (value: string): boolean => {
    13	  if (value === "") return true;
    14	  try {
    15	    const url = new URL(value);
    16	    const protocol = url.protocol.toLowerCase();
    17	    if (protocol === "obsidian:") return isAllowedObsidianUrl(url);
    18	    return ALLOWED_WEB_PROTOCOLS.has(protocol);
    19	  } catch {
    20	    return false;
    21	  }
    22	};
    23	
    24	export const isObsidianUrl = (url: string): boolean =>
    25	  url.toLowerCase().startsWith("obsidian:");
    26	
    27	// Text links live in `meta`, which tldraw validates as arbitrary JSON, so every
    28	// read is untrusted: a hand-edited or synced canvas can hold anything.
    29	export const getTextShapeLinkUrl = (shape: TLShape): string => {
    30	  const url = (shape.meta as { url?: unknown }).url;
    31	  return typeof url === "string" && isAllowedTextLinkUrl(url) ? url : "";
    32	};
