  1	import React, { useCallback } from "react";
  2	import { useEditor, useValue, stopEventPropagation, TLShapeId } from "tldraw";
  3	import DiscourseGraphPlugin from "~/index";
  4	import { EXTERNAL_LINK_ICON_SVG } from "~/icons";
  5	import {
  6	  getTextShapeLinkUrl,
  7	  isObsidianUrl,
  8	} from "~/components/canvas/utils/textShapeLink";
  9	import {
 10	  parseObsidianOpenUrl,
 11	  resolveObsidianUrlToFile,
 12	} from "~/components/canvas/utils/externalContentHandlers";
 13	import {
 14	  openFileInNewLeaf,
 15	  openFileInNewTab,
 16	  openFileInSidebar,
 17	} from "~/components/canvas/utils/openFileUtils";
 18	import { showToast } from "~/components/canvas/utils/toastUtils";
 19	
 20	const LINK_ICON_MASK = `url("data:image/svg+xml;utf8,${encodeURIComponent(
 21	  EXTERNAL_LINK_ICON_SVG,
 22	)}") center 100% / 100% no-repeat`;
 23	
 24	// Matches tldraw's own HyperlinkButton, which hides itself when zoomed out.
 25	const HIDE_BELOW_ZOOM = 0.32;
 26	
 27	type TextLink = { id: TLShapeId; url: string; left: number; top: number };
 28	
 29	type TextLinkOverlayProps = { plugin: DiscourseGraphPlugin };
 30	
 31	// Rendered here, not on a custom shape util, so the stock text shape stays
 32	// untouched -- at the cost of rotation, frame clipping and stacking fidelity.
 33	export const TextLinkOverlay = ({ plugin }: TextLinkOverlayProps) => {
 34	  const editor = useEditor();
 35	
 36	  const links = useValue<TextLink[]>(
 37	    "textShapeLinks",
 38	    () => {
 39	      if (editor.getZoomLevel() < HIDE_BELOW_ZOOM) return [];
 40	      return editor.getCurrentPageShapes().flatMap<TextLink>((shape) => {
 41	        if (shape.type !== "text") return [];
 42	        const url = getTextShapeLinkUrl(shape);
 43	        if (!url) return [];
 44	        const bounds = editor.getShapePageBounds(shape.id);
 45	        if (!bounds) return [];
 46	        const topRight = editor.pageToViewport({
 47	          x: bounds.maxX,
 48	          y: bounds.minY,
 49	        });
 50	        const bottomRight = editor.pageToViewport({
 51	          x: bounds.maxX,
 52	          y: bounds.maxY,
 53	        });
 54	        return [
 55	          {
 56	            id: shape.id,
 57	            url,
 58	            left: topRight.x,
 59	            top: (topRight.y + bottomRight.y) / 2,
 60	          },
 61	        ];
 62	      });
 63	    },
 64	    [editor],
 65	  );
 66	
 67	  const openLink = useCallback(
 68	    (event: React.MouseEvent<HTMLAnchorElement>, url: string) => {
 69	      if (!isObsidianUrl(url)) return;
 70	      // Swallow every obsidian: href, parseable or not. Falling through hands
 71	      // the URI to the OS handler, which runs it against the reader's vault.
 72	      event.preventDefault();
 73	
 74	      const parsed = parseObsidianOpenUrl(url);
 75	      const file = parsed ? resolveObsidianUrlToFile(plugin, parsed) : null;
 76	      if (!file) {
 77	        showToast({
 78	          severity: "warning",
 79	          title: "Cannot open link",
 80	          description: "The linked file is not in this vault",
 81	        });
 82	        return;
 83	      }
 84	
 85	      // Mirrors the discourse-node gestures in TldrawViewComponent.
 86	      const open = event.altKey
 87	        ? openFileInNewLeaf
 88	        : event.metaKey || event.ctrlKey
 89	          ? openFileInNewTab
 90	          : openFileInSidebar;
 91	      void open(plugin.app, file);
 92	      editor.selectNone();
 93	    },
 94	    [editor, plugin],
 95	  );
 96	
 97	  // Upstream lets shift-click through so the canvas can still select the shape.
 98	  const stopUnlessShift = useCallback(
 99	    (event: React.PointerEvent<HTMLAnchorElement>) => {
100	      if (!editor.inputs.shiftKey) stopEventPropagation(event);
101	    },
102	    [editor],
103	  );
104	
105	  return (
106	    <div style={{ position: "absolute", inset: 0, pointerEvents: "none" }}>
107	      {links.map(({ id, url, left, top }) => (
108	        <a
109	          key={id}
110	          className="tl-hyperlink-button"
111	          style={{
112	            position: "absolute",
113	            left: `${left}px`,
114	            top: `${top}px`,
115	            transform: "translateY(-50%)",
116	            pointerEvents: "all",
117	          }}
118	          href={url}
119	          target="_blank"
120	          rel="noopener noreferrer"
121	          onClick={(event) => openLink(event, url)}
122	          onPointerDown={stopUnlessShift}
123	          onPointerUp={stopUnlessShift}
124	          title={url}
125	          draggable={false}
126	        >
127	          <div
128	            className="tl-hyperlink__icon"
129	            style={{ mask: LINK_ICON_MASK, WebkitMask: LINK_ICON_MASK }}
130	          />
131	        </a>
132	      ))}
133	    </div>
134	  );
135	};

